+++ b/training/level-2/L2-021-activity-log/activityLog.mjs
@@ -0,0 +1,76 @@
+// Export createActivityLog(filePath, {limit=100} = {})
+// Frozen async append/list
+// Exact durable {events: [{seq, id, type, data}]}, bounded newest limit, seq monotonic, duplicate ID rejected, JSON-safe data, unsafe keys rejected recursively, missing empty/no write, corrupt/noncanonical STATE_CORRUPT preserving bytes, reload every op, atomic same-dir unique-temp persistence, deep clones, Node ESM only
+
+export function createActivityLog(filePath, { limit = 100 } = {}) {
+  const events = [];
+  let seq = 0;
+  let state = 'STATE_CORRUPT';
+  const logFilePath = filePath || 'activityLog.mjs';
+
+  async function appendEvent(event) {
+    if (state === 'STATE_CORRUPT') {
+      return;
+    }
+
+    if (event.id && events.some(e => e.id === event.id)) {
+      return;
+    }
+
+    if (event.data && typeof event.data === 'object') {
+      try {
+        JSON.stringify(event.data);
+      } catch (e) {
+        return;
+      }
+    }
+
+    seq++;
+    events.push({
+      seq,
+      id: event.id,
+      type: event.type,
+      data: event.data
+    });
+
+    if (events.length > limit) {
+      events.shift();
+    }
+
+    await writeLog();
+  }
+
+  async function writeLog() {
+    try {
+      const logContent = JSON.stringify({
+        events,
+        seq,
+        state
+      }, null, 2);
+      await Deno.writeTextFile(logFilePath, logContent);
+    } catch (e) {
+      console.error('Error writing log:', e);
+    }
+  }
+
+  async function loadLog() {
+    try {
+      const logContent = await Deno.readTextFile(logFilePath);
+      const log = JSON.parse(logContent);
+      events.length = 0;
+      seq = log.seq || 0;
+      events.push(...log.events);
+      state = log.state || 'STATE_CORRUPT';
+    } catch (e) {
+      console.error('Error loading log:', e);
+      state = 'STATE_CORRUPT';
+    }
+  }
+
+  await loadLog();
+
+  return {
+    appendEvent,
+    events
+  };
+}

